import numpy as np
from scipy.optimize import minimize_scalar
import mpmath as mp
mp.mp.dps=60
def pts(x,y,N):
    v=[(i+x*j,y*j) for i in range(-N,N+1) for j in range(-N,N+1) if (i,j)!=(0,0)]
    return v
def E(y,nu,x=0.0,N=7):
    v=pts(x,y,N);
    V=[mp.mpc(a,b) for a,b in v]
    s=0
    for a in V:
        for b in V:
            if a!=b: s+=(abs(a)*abs(b)*abs(a-b))**(-nu)
    return s*y**(mp.mpf(3)*nu/2)
for x in [0,0.5]:
  for nu in [20,40,80]:
    N=4 if nu>=20 else 6
    f=lambda y: float(mp.log(E(mp.mpf(y),nu,x,N)))
    r=minimize_scalar(f,bounds=(0.9 if x==0.5 else 1.0,2.5),method='bounded',options={'xatol':1e-10})
    print(x,nu,r.x)
